const themeMap = {
  light: lightColors,
  dark: darkColors,
} as const;

export const resolveColors = (
  theme: 'light' | 'dark',
  overrides?: TEliteaAssistantColors,
): Required<TEliteaAssistantColors> => ({
  ...themeMap[theme],
  ...overrides,
});

